targets.expr:
sum by (source, target, service_name, detected_level) (
  count_over_time(
    {job="lgtm/docker"}
      | label_format source=`{{.service_name}}`, target=`{{.detected_level}}`
      | target != ""
      | logfmt
    [$__auto]
  )
)

